     "해설": "점 \\(\\mathrm{I} \\left( a, b \\right)\\)는 두 직선 \\(12x-5y+60=0\\), \\(y=0\\)이 이루는 각을 이등분하며 기울기가 양수인 직선 위의 점이다.\n\\(\\displaystyle \\frac{\\left| 12a-5b+60 \\right|}{13}\\)\\({}= \\left| b \\right|\\),\n\\(12a-5b+60=13b\\) 또는 \\(12a-5b+60=-13b\\),\n\\(2a-3b+10=0\\) 또는 \\(3a+2b+15= 0\\)\n이때 기울기가 양수인 직선 위의 점이므로 점 \\(\\mathrm{I}\\)의 자취의 방정식은\n\\(2x-3y+10=0\\)\\(\\cdots \\cdots\\) ㉠\n점 \\(\\mathrm{I} \\left( a, b \\right)\\)는 두 직선 \\(3x+4y-12=0\\), \\(y=0\\)이 이루는 각을 이등분하며 기울기가 음수인 직선 위의 점이다.\n\\(\\displaystyle \\frac{\\left| 3a+4b-12 \\right|}{5} = \\left| b \\right|\\),\n\\(3a+4b-12=5b\\) 또는 \\(3a+4b-12= -5b\\),\n\\(3a-b-12=0\\) 또는 \\(a+3b-4=0\\)\n이때 기울기가 양수인 직선 위의 점이므로 점 \\(\\mathrm{I}\\)의 자취의 방정식은\n\\(x+3y-4=0\\)\\(\\cdots \\cdots\\) ㉡\n좀 \\(\\mathrm{I}\\)는 두 직선 ㉠, ㉡의 교점이므로 두 식을 연립하여 풀면\n\\(\\therefore \\mathrm{I} \\left( -2, 2 \\right)\\)\n삼각형의 세 직선의 교점을 꼭짓점으로 하는 삼각형이므로\n각각 연립하여 풀면 \\(\\left( -5, 0 \\right)\\), \\(\\left( 4, 0 \\right)\\), \\(\\displaystyle \\left( - \\frac{20}{7} , \\frac{36}{7} \\right)\\)으로\n\\(\\left( -2, 2 \\right)\\)에서 거리가 가장 큰 값은\n\\(\\therefore \\sqrt{\\left( 4+2 \\right) ^{2} + \\left( 0-2 \\right) ^{2}} =2 \\sqrt{10}\\)"
