    "유사": {
     "stem": "원 $x^{2}+y^{2}=16$과 직선 $y=\\sqrt{3}x$의 제 1사분면 교점을 $\\mathrm{P}$, 직선 $\\displaystyle y=\\frac{\\sqrt{3}}{3}x$의 제 1사분면 교점을 $Q$라 하자. 호 $PQ$ 위의 고정점 $\\mathrm{C}$와 선분 $\\mathrm{OP}$, $OQ$ 위의 움직이는 점 $\\mathrm{A}$, $\\mathrm{B}$를 꼭짓점으로 하는 삼각형 $\\mathrm{ABC}$의 둘레의 최솟값은? (단, $\\mathrm{O}$는 원점)",
     "choices": [
      "① $\\displaystyle \\frac{4 \\sqrt{3}}{3}$",
      "② $2 \\sqrt{2}$",
      "③ $4$",
      "④ $4 \\sqrt{2}$",
      "⑤ $4 \\sqrt{3}$"
     ],
     "answer": "③",
     "id": "ngd_gs_b902daea7e",
     "출처": "학교 기출(족보)",
     "해설": "원 \\(x^2+y^2=16\\)의 반지름은 \\(4\\)이다.\n직선 \\(y=\\sqrt{3}x\\)는 \\(x\\)축과 \\(60^\\circ\\)의 각을 이루므로, 제1사분면 교점 \\(\\mathrm{P}\\)는 반지름 \\(4\\)인 점 중 각 \\(60^\\circ\\) 위치: \\(\\mathrm{P}=(4\\cos60^\\circ,4\\sin60^\\circ)\\).\n직선 \\(\\displaystyle y=\\frac{\\sqrt{3}}{3}x\\)는 \\(x\\)축과 \\(30^\\circ\\)의 각을 이루므로, \\(\\mathrm{Q}=(4\\cos30^\\circ,4\\sin30^\\circ)\\).\n따라서 \\(\\mathrm{OP}\\)는 각 \\(60^\\circ\\) 방향의 반직선, \\(\\mathrm{OQ}\\)는 각 \\(30^\\circ\\) 방향의 반직선이고, 두 반직선 사이의 각 \\(\\angle \\mathrm{POQ}=30^\\circ\\)이다. 점 \\(\\mathrm{C}\\)는 호 \\(\\mathrm{PQ}\\) 위, 즉 각 \\(\\theta\\in[30^\\circ,60^\\circ]\\), 반지름 \\(4\\)인 점이다.\n삼각형 \\(\\mathrm{ABC}\\) (\\(\\mathrm{A}\\in \\mathrm{OP}\\), \\(\\mathrm{B}\\in \\mathrm{OQ}\\), \\(\\mathrm{C}\\) 고정)의 둘레 \\(\\mathrm{CA}+\\mathrm{AB}+\\mathrm{BC}\\)를 최소화하려면, \\(\\mathrm{C}\\)를 직선 \\(\\mathrm{OP}\\)에 대해 대칭이동한 점 \\(\\mathrm{C}_1\\)과 직선 \\(\\mathrm{OQ}\\)에 대해 대칭이동한 점 \\(\\mathrm{C}_2\\)를 잡아 \\(\\mathrm{CA}+\\mathrm{AB}+\\mathrm{BC} = \\mathrm{C}_1\\mathrm{A}+\\mathrm{AB}+\\mathrm{BC}_2 \\ge \\overline{\\mathrm{C}_1\\mathrm{C}_2}\\) (등호는 \\(\\mathrm{A},\\mathrm{B}\\)가 선분 \\(\\mathrm{C}_1\\mathrm{C}_2\\) 위에 있을 때)를 이용한다.\n점 \\(\\mathrm{C}\\)가 각 \\(\\theta\\)에 있다고 하면, 직선 \\(\\mathrm{OP}\\)(각 \\(60^\\circ\\))에 대한 대칭점 \\(\\mathrm{C}_1\\)은 각 \\(2\\cdot60^\\circ-\\theta=120^\\circ-\\theta\\), 반지름 \\(4\\)인 점이고, 직선 \\(\\mathrm{OQ}\\)(각 \\(30^\\circ\\))에 대한 대칭점 \\(\\mathrm{C}_2\\)는 각 \\(2\\cdot30^\\circ-\\theta=60^\\circ-\\theta\\), 반지름 \\(4\\)인 점이다.\n두 점 \\(\\mathrm{C}_1,\\mathrm{C}_2\\) 사이의 각은\n\\[(120^\\circ-\\theta)-(60^\\circ-\\theta)=60^\\circ\\]\n로 \\(\\theta\\)에 관계없이 항상 \\(60^\\circ\\)이고, \\(\\mathrm{OC}_1=\\mathrm{OC}_2=4\\)이다.\n따라서 코사인법칙에 의해\n\\[\\overline{\\mathrm{C}_1\\mathrm{C}_2}^2 = 4^2+4^2-2\\cdot4\\cdot4\\cos60^\\circ = 16+16-16=16\\]\n이므로 \\(\\overline{\\mathrm{C}_1\\mathrm{C}_2}=4\\).\n즉 둘레의 최솟값은 \\(\\mathrm{C}\\)의 위치와 관계없이 \\(4\\)이다.\n따라서 정답은 ③ 이다."
    }
