     "해설": "\\(p \\to \\sim q\\)가 거짓이 되려면 전제 \\(p\\)가 참이고 결론 \\(\\sim q\\)가 거짓이어야 한다. 즉 \\(x \\in P\\)이면서 동시에 \\(\\sim q\\)가 거짓, 곧 \\(x \\in Q\\)인 원소 \\(x\\)가 존재해야 한다. 따라서 \\(x \\in P\\)이고 \\(x \\in Q\\)이므로 \\(x \\in P \\cap Q\\)이다. \\(P - Q\\)는 \\(p \\to q\\) 거짓의 경우, \\(Q - P\\)는 \\(\\sim p \\to \\sim q\\) 거짓의 경우이므로 혼동에 주의한다."
