     "출처": "학교 기출(족보)",
     "해설": "\\(f\\)가 역함수를 가지므로 \\(f\\)는 \\(X\\)에서 \\(X\\)로의 일대일 대응이다.\n\\(f(1)=2,\\ f(2)=3\\)이 주어졌으므로, 나머지 원소에 의해 \\(f(3)=1\\)이다.\n\\((g \\circ f)(3) = g(f(3)) = g(1) = 3\\)\n\\((f \\circ g)(3) = f(g(3)) = 2\\)이고, \\(f(1)=2\\)이므로 \\(g(3)=1\\)이다.\n\\(g\\)도 일대일 대응이고 \\(g(1)=3,\\ g(3)=1\\)이 확정되었으므로 \\(g(2)=2\\)이다.\n따라서 \\(f(3)-g(1) = 1-3 = -2\\)이다.\n따라서 정답은 ① 이다."
