     "stem": "두 점 $\\mathrm{A}(-5, 4)$, $\\mathrm{B}(2, 3)$와 $x$축 위의 점 $\\mathrm{P}$에 대해 삼각형 $\\mathrm{ABP}$가 직각삼각형이 되도록 하는 모든 점 $\\mathrm{P}$의 $x$좌표의 값의 합은?",
