     "출처": "학교 기출(족보)",
     "해설": "점 \\(\\mathrm{P}(p, 0)\\)이라 하자. \\(\\mathrm{A}(-5,4)\\), \\(\\mathrm{B}(2,3)\\)이므로 각 경우에 대해 직각이 되는 조건을 세운다.\n(ⅰ) 직각이 \\(\\mathrm{A}\\)에 있는 경우: \\(\\vec{\\mathrm{AB}}=(7,-1)\\), \\(\\vec{\\mathrm{AP}}=(p+5,-4)\\)이고 두 벡터가 수직이므로\n\\(\\displaystyle 7(p+5)+(-1)(-4)=0 \\Rightarrow 7p+39=0 \\Rightarrow p=-\\frac{39}{7}\\)\n(ⅱ) 직각이 \\(\\mathrm{B}\\)에 있는 경우: \\(\\vec{\\mathrm{BA}}=(-7,1)\\), \\(\\vec{\\mathrm{BP}}=(p-2,-3)\\)이고 수직이므로\n\\(\\displaystyle -7(p-2)+1\\cdot(-3)=0 \\Rightarrow -7p+11=0 \\Rightarrow p=\\frac{11}{7}\\)\n(ⅲ) 직각이 \\(\\mathrm{P}\\)에 있는 경우: \\(\\vec{\\mathrm{PA}}=(-5-p,4)\\), \\(\\vec{\\mathrm{PB}}=(2-p,3)\\)이고 수직이므로\n\\((-5-p)(2-p)+12=0\\)\n\\(p^2+3p-10+12=0 \\Rightarrow p^2+3p+2=0 \\Rightarrow (p+1)(p+2)=0\\)\n따라서 \\(p=-1\\) 또는 \\(p=-2\\)\n모든 경우 삼각형이 퇴화(일직선)되지 않으므로 모두 유효하다.\n모든 \\(p\\) 값의 합은\n\\(\\displaystyle -\\frac{39}{7}+\\frac{11}{7}+(-1)+(-2) = -\\frac{28}{7} -3 = -4-3=-7\\)\n따라서 정답은 ① 이다."
