     "id": "ngd_gs_f2e6c95d2d",
     "출처": "학교 기출(족보)",
     "해설": "조건 (가)에서 \\(\\overline{\\mathrm{AC}}=\\overline{\\mathrm{BC}}\\)이므로 점 \\(\\mathrm{C}\\)는 선분 \\(\\mathrm{AB}\\)의 수직이등분선 위에 있다.\n\\(\\mathrm{A}(0,6t)\\), \\(\\mathrm{B}(2t,8t)\\)이므로 \\(\\overline{\\mathrm{AB}}\\)의 방향벡터는 \\((2t,2t)\\), 즉 \\((1,1)\\) 방향이고, 중점은 \\(\\mathrm{M}(t,7t)\\)이다. 수직이등분선의 방향벡터는 \\((1,-1)\\)이므로\n\\[\\mathrm{C}=(t+s,\\,7t-s)\\quad(s\\text{는 실수})\\]로 놓을 수 있다.\n점 \\(\\mathrm{P}\\)는 \\(\\overline{\\mathrm{AC}}\\)를 \\(1:6\\)으로 내분하므로\n\\[\\overrightarrow{\\mathrm{CP}}=\\mathrm{P}-\\mathrm{C}=\\frac{6(\\mathrm{A}-\\mathrm{C})}{7}.\\]\n마찬가지로 \\(\\displaystyle \\overrightarrow{\\mathrm{CQ}}=\\dfrac{6(\\mathrm{B}-\\mathrm{C})}{7}\\).\n삼각형 \\(\\mathrm{CPQ}\\)의 무게중심 \\(\\mathrm{G}\\)는\n\\[\\mathrm{G}-\\mathrm{C}=\\frac{(\\mathrm{P}-\\mathrm{C})+(\\mathrm{Q}-\\mathrm{C})}{3}=\\frac{6}{21}\\left[(\\mathrm{A}-\\mathrm{C})+(\\mathrm{B}-\\mathrm{C})\\right]=\\frac{2}{7}\\big[(\\mathrm{A}+\\mathrm{B})-2\\mathrm{C}\\big].\\]\n\\(\\displaystyle \\mathrm{M}=\\dfrac{\\mathrm{A}+\\mathrm{B}}{2}\\)이므로 \\(\\mathrm{A}+\\mathrm{B}-2\\mathrm{C}=2(\\mathrm{M}-\\mathrm{C})\\), 따라서\n\\[\\mathrm{G}-\\mathrm{C}=\\frac{4}{7}(\\mathrm{M}-\\mathrm{C})\\ \\Rightarrow\\ \\overline{\\mathrm{CG}}=\\frac{4}{7}\\overline{\\mathrm{CM}}.\\]\n\\(\\overline{\\mathrm{CG}}=4\\sqrt{2}\\)이므로\n\\[\\overline{\\mathrm{CM}}=\\frac{7}{4}\\cdot 4\\sqrt{2}=7\\sqrt{2}.\\]\n\\(\\mathrm{M}-\\mathrm{C}=(-s,s)\\)이므로 \\(\\overline{\\mathrm{CM}}=|s|\\sqrt{2}=7\\sqrt{2}\\), 즉 \\(|s|=7\\).\n따라서 \\(\\mathrm{C}\\)의 \\(x\\)좌표 \\(a=t+s=t\\pm7\\)이므로\n\\[|t-a| = |\\mp 7| = 7.\\]\n따라서 정답은 ④ 이다."
