     "stem": "점 $(a, b)$를 $x$축에 대하여 대칭이동한 다음 직선 $y=-x$에 대하여 대칭이동하였더니 제2사분면 위의 점이 되었다.\n<보기>\nㄱ. $a<0$, $b<0$\nㄴ. $a+b$는 음수이다.\nㄷ. 점 $\\displaystyle \\left( \\frac{b}{a}, a-b \\right)$는 제4사분면 위의 점이다.",
