     "해설": "점 \\((a,b)\\)를 \\(x\\)축에 대하여 대칭이동하면 \\((a,-b)\\)가 된다.\n이 점을 직선 \\(y=-x\\)에 대하여 대칭이동하면, 일반적으로 점 \\((x,y)\\)를 \\(y=-x\\)에 대하여 대칭이동하면 \\((-y,-x)\\)가 되므로, \\((a,-b) \\to (-(-b), -a) = (b, -a)\\)가 된다.\n이 점 \\((b,-a)\\)가 제2사분면 위의 점이므로\n\\(b<0,\\quad -a>0 \\Rightarrow a<0\\)\n따라서 \\(a<0,\\ b<0\\)이다. → ㄱ은 참이다.\nㄴ. \\(a<0,\\ b<0\\)이므로 \\(a+b<0\\), 즉 \\(a+b\\)는 음수이다. → ㄴ은 참이다.\nㄷ. 점 \\(\\displaystyle \\left(\\dfrac{b}{a}, a-b\\right)\\)를 살펴보면,\n\\(a<0,\\ b<0\\)이므로 \\(\\displaystyle \\dfrac{b}{a} = \\dfrac{(-)}{(-)} >0\\)이다.\n\\(a-b = a-b\\)에서 \\(a<0,\\ -b>0\\)이므로 \\(a-b\\)의 부호는 \\(|a|\\)와 \\(|b|\\)의 크기 관계에 따라 양수 또는 음수가 될 수 있다. 예를 들어 \\(a=-1,b=-2\\)이면 \\(a-b=1>0\\)이고, \\(a=-2,b=-1\\)이면 \\(a-b=-1<0\\)이다.\n따라서 \\(a-b\\)의 부호가 일정하게 결정되지 않으므로, 점 \\(\\displaystyle \\left(\\dfrac{b}{a}, a-b\\right)\\)가 항상 제4사분면 위의 점이라고 할 수 없다. → ㄷ은 거짓이다.\n따라서 옳은 것은 ㄱ, ㄴ이므로 정답은 ③ 이다."
