     "answer": "④",
     "id": "ngd_su2_b707aee0f8",
     "출처": "학교 기출(족보)",
     "해설": "\\(x \\neq 0\\)일 때 \\(|x|f(x)=x\\) 이므로 \\(\\displaystyle f(x)=\\dfrac{x}{|x|}\\) 이다. 즉 \\(f(x)=1\\;(x>0)\\), \\(f(x)=-1\\;(x<0)\\), \\(f(0)=0\\) 이다. 또 \\(g(x)=x-x^2=x(1-x)\\) 이다.\nㄱ. \\(x\\to 0\\) 근처에서 \\(1-x>0\\) 이므로 \\(g(x)\\)의 부호는 \\(x\\)의 부호와 같다. 따라서 \\(x\\to 0^+\\) 이면 \\(g(x)>0\\) 이므로 \\(f(g(x))=1\\), \\(x\\to 0^-\\) 이면 \\(g(x)<0\\) 이므로 \\(f(g(x))=-1\\) 이다. 좌우극한이 달라 \\(\\lim\\limits_{x\\to 0}f(g(x))\\) 는 존재하지 않는다.\nㄴ. \\(\\lim\\limits_{x\\to 0}g(x)=0-0=0\\) 이므로 \\(f\\left(\\lim\\limits_{x\\to 0}g(x)\\right)=f(0)=0\\) 으로 존재한다.\nㄷ. \\(x\\to 0^+\\) 이면 \\(f(x)=1\\), \\(x\\to 0^-\\) 이면 \\(f(x)=-1\\) 이므로 \\(\\lim\\limits_{x\\to 0}f(x)\\) 자체가 존재하지 않는다. 따라서 \\(g\\left(\\lim\\limits_{x\\to 0}f(x)\\right)\\) 는 값이 정해지지 않아 존재하지 않는다.\nㄹ. \\(|f(x)|\\le 1\\) 이고 \\(g(x)\\to 0\\) 이므로 \\(|f(x)g(x)|\\le |g(x)|\\to 0\\), 조임정리에 의해 \\(\\lim\\limits_{x\\to 0}f(x)g(x)=0\\) 으로 존재한다.\nㅁ. \\(x>0\\) 이면 \\(f(x)=1\\) 이므로 \\(\\displaystyle \\dfrac{g(x)}{f(x)}=g(x)\\to 0\\), \\(x<0\\) 이면 \\(f(x)=-1\\) 이므로 \\(\\displaystyle \\dfrac{g(x)}{f(x)}=-g(x)\\to 0\\). 좌우극한이 모두 \\(0\\) 으로 같으므로 \\(\\displaystyle \\lim\\limits_{x\\to 0}\\dfrac{g(x)}{f(x)}=0\\) 으로 존재한다.\n따라서 극한값이 존재하는 것은 ㄴ, ㄹ, ㅁ 이므로 정답은 ④ 이다."
