     "해설": "\\(f(x)=x^3+bx^2+cx+d\\) (최고차항 계수 1)라 하면 (가)에서 \\(xg(x)=f(x)-f(0)=x^3+bx^2+cx=x(x^2+bx+c)\\)이므로 \\(g(x)=x^2+bx+c\\) (\\(x>0\\)).\n(나)에서 \\(g\\)의 최솟값이 \\(0\\)이려면 꼭짓점이 \\(x>0\\)에 있어야 하므로 \\(\\displaystyle -\\frac{b}{2}>0\\)이고 최솟값 \\(\\displaystyle c-\\frac{b^2}{4}=0\\), 즉 \\(\\displaystyle c=\\frac{b^2}{4}\\)이다.\n꼭짓점을 \\(\\displaystyle x_0=-\\frac{b}{2}>0\\)라 하면 \\(g(x)=(x-x_0)^2\\), \\(b=-2x_0,\\ c=x_0^2\\)이고 \\(f'(x)=3x^2-4x_0x+x_0^2\\)이다.\n(다)에서 \\(f'(x)-g(a)=0\\)의 두 근이 \\(\\displaystyle a,\\ \\frac{5}{3}\\)이므로\n근과 계수의 관계: \\(\\displaystyle a+\\frac{5}{3}=\\frac{4x_0}{3}\\) ⇒ \\(\\displaystyle x_0=\\frac{3a+5}{4}\\)\n\\(\\displaystyle a\\cdot\\frac{5}{3}=\\dfrac{x_0^2-(a-x_0)^2}{3}=\\dfrac{a(2x_0-a)}{3}\\) (단 \\(a\\ne0\\))이므로 \\(5=2x_0-a\\), 즉 \\(a=2x_0-5\\).\n두 식을 연립하면 \\(\\displaystyle a=\\frac{3a-5}{2}\\)에서 \\(a=5\\), \\(x_0=5\\).\n따라서 \\(g(x)=(x-5)^2\\), \\(f'(x)=3x^2-20x+25\\) (검산: \\(3x^2-20x+25=0\\)의 근은 \\(\\displaystyle x=5,\\frac{5}{3}\\), \\(g(5)=0\\)과 일치).\n\\(A_m=\\{x\\mid f'(x)=g(m),\\ 0<x\\le m\\}\\)에서 \\(k=(m-5)^2\\)이라 하면 \\(3x^2-20x+25=k\\)의 두 근은\n\\(\\displaystyle x=\\dfrac{10\\pm\\sqrt{25+3k}}{3}\\).\n작은 근 \\(\\displaystyle x_1=\\dfrac{10-\\sqrt{25+3k}}{3}>0 \\iff \\sqrt{25+3k}<10 \\iff k<25 \\iff (m-5)^2<25 \\iff 0<m<10\\).\n큰 근 \\(\\displaystyle x_2=\\dfrac{10+\\sqrt{25+3k}}{3}\\le m\\)이 되려면 (단 \\(\\displaystyle m\\ge\\frac{10}{3}\\) 필요) 양변 제곱하여 정리하면\n\\(3m^2-30m+100\\le 9m^2-60m+100 \\iff 6m(m-5)\\ge0 \\iff m\\ge5\\) (자연수 조건에서).\n따라서 두 근이 모두 \\((0,m]\\)에 속하려면 \\(5\\le m<10\\), 즉 \\(m=5,6,7,8,9\\).\n(이때 \\(n(A_m)=2\\)이고, \\(m\\le4\\)에서는 \\(x_2>m\\)이라 \\(n=1\\), \\(m\\ge10\\)에서는 \\(x_1\\le0\\)이라 \\(n\\le1\\)임을 확인할 수 있다.)\n따라서 구하는 합은 \\(5+6+7+8+9=35\\)이다.\n따라서 정답은 ① 이다."
