     "출처": "학교 기출(족보)",
     "해설": "자동차는 \\(4\\)시간 동안 \\(200\\mathrm{km}\\)를 이동하였으므로 평균속도는 \\(\\displaystyle v_{avg}=\\dfrac{200}{4}=50\\mathrm{km}/h\\) 이다. 따라서 ㄱ은 항상 옳다.\nㄴ: 최고속도가 반드시 \\(200\\mathrm{km}/h\\) 이어야 한다는 조건은 없다. 예를 들어 처음부터 끝까지 일정하게 \\(50\\mathrm{km}/h\\)로 달렸다면 조건을 만족하면서도 최고속도는 \\(50\\mathrm{km}/h\\) 이다. 따라서 ㄴ은 항상 옳은 것이 아니다.\nㄷ: \"출발 후 \\(2\\)시간 동안 \\(100\\mathrm{km}\\)를 달렸다\"는 조건은 반드시 성립하지 않는다. 예를 들어 처음 \\(2\\)시간은 천천히(예: \\(0\\mathrm{km}\\)~\\(80\\mathrm{km}\\)) 이동하고 나머지 \\(2\\)시간에 \\(120\\mathrm{km}\\)를 이동하는 등 평균속도 \\(50\\mathrm{km}/h\\), 총거리 \\(200\\mathrm{km}\\)를 만족하면서도 정확히 \\(2\\)시간에 \\(100\\mathrm{km}\\)가 아닐 수 있다. 따라서 ㄷ은 항상 옳은 것이 아니다.\nㄹ: 자동차의 속도는 출발 시 \\(0\\)에서 시작하여 도착 시 \\(0\\)으로 끝나는 연속함수로 생각할 수 있고, 평균속도는 \\(50\\mathrm{km}/h\\) 이다. 평균값 정리(또는 중간값 정리)에 의해 속도가 연속적으로 변화한다면, 출발부터 도착까지 어느 순간에는 반드시 평균속도와 같은 \\(50\\mathrm{km}/h\\)의 속도를 가지는 순간이 존재한다. 따라서 ㄹ은 항상 옳다.\n따라서 항상 옳은 것은 ㄱ, ㄹ이다.\n따라서 정답은 ③ 이다."
