    "마지막오답": "2026-11-03",
    "강의": null,
    "답변": [],
    "유사": {
     "stem": "최고차항의 계수가 양수인 삼차함수 $f \\left( x \\right)$가 다음 조건을 만족시킬 때, 함수 $f \\left( x \\right)$의 극댓값과 극솟값의 합은?\n(가) 어떤 다항함수 $g \\left( x \\right)$와 모든 실수 $x$에 대하여 $f \\left( x \\right) g \\left( x \\right) = \\left( x ^{2} -a \\right) ^{3}$이다. (단, $a$는 상수이다.)\n(나) 곡선 $y=f \\left( x \\right)$가 점 $\\left( 0, 3 \\right)$에서 직선 $y=-x+3$에 접한다.",
     "choices": [
      "① $\\displaystyle \\frac{29}{9}$",
      "② $\\displaystyle \\frac{10}{3}$",
      "③ $\\displaystyle \\frac{31}{9}$",
      "④ $\\displaystyle \\frac{32}{9}$",
      "⑤ $\\displaystyle \\frac{11}{3}$"
     ],
     "answer": "④",
     "id": "ngd_su2_0b3788f0fc",
     "출처": "학교 기출(족보)",
     "해설": "조건 (가)에서 \\(f(x)g(x)=(x^{2}-a)^{3}=(x-\\sqrt{a})^{3}(x+\\sqrt{a})^{3}\\) 이고 \\(f(x)\\)는 삼차함수이므로, \\(f(x)\\)는 \\((x-\\sqrt{a})^{i}(x+\\sqrt{a})^{j}\\) \\((i+j=3)\\) 꼴이어야 한다. (단 \\(a>0\\))\n조건 (나)에서 \\(f(0)=3\\), \\(f'(0)=-1\\) 이다.\n\\(i=3, j=0\\)일 때: \\(f(x)=c(x-\\sqrt a)^{3}\\), \\(f(0)=-c a^{3/2}=3\\), \\(f'(0)=3ca=-1\\)에서 \\(c a^{1/2}/3 \\cdot 3= \\cdots\\) 을 정리하면 \\(\\displaystyle c=-\\frac{1}{3a}<0\\)이 되어 최고차항 계수가 양수라는 조건에 모순.\n\\(i=0,j=3\\)일 때: \\(f(0)=ca^{3/2}=3\\), \\(f'(0)=3ca=-1\\)에서 \\(a^{3/2}=-9\\)가 되어 불가능.\n\\(i=1,j=2\\)일 때: \\(f(x)=c(x-\\sqrt a)(x+\\sqrt a)^2\\), \\(f(0)=-ca^{3/2}=3\\), \\(f'(0)=-ca=-1\\)에서 \\(ca=1\\), 이를 대입하면 \\(\\sqrt a=-3\\)이 되어 불가능.\n\\(i=2,j=1\\)일 때: \\(f(x)=c(x-\\sqrt a)^2(x+\\sqrt a)\\).\n\\(f(0)=ca^{3/2}=3\\), \\(\\displaystyle f'(0)=-ca=-1 \\Rightarrow ca=1 \\Rightarrow c=\\frac{1}{a}\\).\n대입하면 \\(\\sqrt a=3 \\Rightarrow a=9\\), \\(\\displaystyle c=\\frac{1}{9}\\).\n따라서 \\(\\displaystyle f(x)=\\frac{1}{9}(x-3)^{2}(x+3)\\).\n전개하면 \\(\\displaystyle f(x)=\\frac{1}{9}x^{3}-\\frac{1}{3}x^{2}-x+3\\) 이고 \\(f(0)=3\\), \\(f'(0)=-1\\)을 만족함을 확인할 수 있다.\n\\(\\displaystyle f'(x)=\\frac{1}{3}x^{2}-\\frac{2}{3}x-1=\\frac{1}{3}(x-3)(x+1)\\) 이므로 극값은 \\(x=-1\\) 에서 극대, \\(x=3\\)에서 극소이다.\n\\(\\displaystyle f(-1)=\\frac{1}{9}(-4)^{2}(2)=\\frac{32}{9}\\), \\(f(3)=0\\).\n극댓값과 극솟값의 합은 \\(\\displaystyle \\frac{32}{9}+0=\\frac{32}{9}\\).\n따라서 정답은 ④ 이다."
    }
